        while end >= 0 and row[end] == bg:
            end -= 1
        if end < 0 or end == w - 1 or row[end] == bg:
            continue

        color = row[end]
        # The trailing background is an interrupted continuation of a line,
        # or this row is a repeated pattern row below its original.
        supported = any(other != r and grid[other][end + 1] == color
                        for other in range(h))
        repeated = any(
            other < r and grid[other][:end + 1] == row[:end + 1]
            for other in range(h)
        )
        if supported or repeated:
            for c in range(end + 1, w):
                out[r][c] = 1

    return out
