    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        # Locate the trailing run of the background color.
        k = w
        while k > 0 and row[k - 1] == bg:
            k -= 1
        if k == w or k == 0:
            continue

        # If another row has the same prefix and continues the pattern,
        # color the missing continuation.
        for s, ref in enumerate(grid):
            if s == r or ref[:k] != row[:k]:
                continue
            if any(v != bg for v in ref[k:]):
                for c in range(k, w):
                    if row[c] == bg and ref[c] != bg:
                        out[r][c] = 1
                break

    return out
